#!/usr/bin/env python3
"""
Round 115b (culprits), 29 September 2026. Needs round 114b.

The medical industry's culprits row (from the Suppression page's medical section).

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''

NOTE = '## Round 115b (29 September)\n\nNeeds round 114b. Tiles patch round115b_tiles.py beside it (it also carries\nlib/wdtools.py, so it works whether or not 114b_tiles went first).\n\n- medical_culprits (Suppression > The medical industry), from the owner\'s\n  suppression.html medical section (first half: paid prescribing,\n  overprescribing addictive drugs, marketing, Bayer and others\' HIV-tainted\n  clotting products). Tiles medical_culprits.py: every row of Wikipedia\'s List\n  of largest pharmaceutical settlements (company linked article -> Wikidata\n  HQ), plus a compiled list (opioid makers, distributors, pharmacies,\n  Sacklers, McKinsey; Cutter/Bayer, Baxter, Alpha Therapeutic, Armour) kept\n  only if the cited Wikipedia article names them (whole word) at build time;\n  the box quotes those sentences; dropped names in medical/build.json.\n- Schools: the page\'s list (school section) was already mapped in round\n  105b; NWEA is inside the HMH entry. Not mapped: the "Global Education\n  Forum" (unclear which body) and university fossil-fuel investments\n  (mappingfossilties.org, not read yet).\n- Tiles capture_stb.py (the other chat\'s): the office-holder query timed out\n  (504); now asked per country, then per 25-year birth span, with retries.\n\n'
HEAD = '## Round 115b (29 September)'


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round115b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if "## Round 114b" not in text:
        sys.exit("round115b: round 114b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round115b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round115b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round115b: applied")
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round ")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
